/**
 * Minimal PDF text extractor (Node built-ins only): inflates FlateDecode streams, reads ToUnicode CMaps, decodes Tj/TJ strings per font
 * (simple fonts: bytes; Identity-H fonts: 2-byte codes). Good enough for specification PDFs generated by Word; not a general PDF parser.
 * usage: node pdf-text.mjs <file.pdf> [out.txt]
 */
import { readFileSync, writeFileSync } from "node:fs";
import { inflateSync } from "node:zlib";

const file = process.argv[2];
const buf = readFileSync(file);
const latin = buf.toString("latin1");
const BS = String.fromCharCode(92); // backslash, avoids escaping mistakes in regex literals below

// 1) objects
const objs = new Map();
const re = /(\d+) (\d+) obj([\s\S]*?)endobj/g;
let m;
while ((m = re.exec(latin))) {
  const id = +m[1];
  const body = m[3];
  const si = body.indexOf("stream");
  const dict = si >= 0 ? body.slice(0, si) : body;
  let data = null;
  if (si >= 0) {
    let s = m.index + m[0].indexOf("stream") + 6;
    if (latin[s] === "\r") s += 1;
    if (latin[s] === "\n") s += 1;
    const e = latin.indexOf("endstream", s);
    data = buf.subarray(s, e);
    if (/FlateDecode/.test(dict)) {
      try { data = inflateSync(data); } catch { try { data = inflateSync(data.subarray(0, data.length - 1)); } catch { data = null; } }
    }
  }
  objs.set(id, { dict, data });
}
// object streams
for (const [, o] of [...objs]) {
  if (/\/Type\s*\/ObjStm/.test(o.dict) && o.data) {
    const n = +/\/N (\d+)/.exec(o.dict)[1];
    const first = +/\/First (\d+)/.exec(o.dict)[1];
    const t = o.data.toString("latin1");
    const nums = t.slice(0, first).trim().split(/\s+/).map(Number);
    for (let i = 0; i < n; i += 1) {
      const oid = nums[2 * i];
      const off = nums[2 * i + 1];
      const end = i + 1 < n ? nums[2 * i + 3] : t.length - first;
      objs.set(oid, { dict: t.slice(first + off, first + end), data: null });
    }
  }
}
// 2) ToUnicode CMaps
const cmaps = new Map();
function getCmap(fontId) {
  if (cmaps.has(fontId)) return cmaps.get(fontId);
  let res = null;
  const f = objs.get(fontId);
  const tu = f && /\/ToUnicode (\d+) 0 R/.exec(f.dict);
  const c = tu && objs.get(+tu[1]);
  if (c && c.data) {
    const t = c.data.toString("latin1");
    const map = new Map();
    for (const b of t.matchAll(/beginbfchar([\s\S]*?)endbfchar/g)) {
      for (const l of b[1].matchAll(/<([0-9a-fA-F]+)>\s*<([0-9a-fA-F]+)>/g)) {
        map.set(parseInt(l[1], 16), String.fromCodePoint(...(l[2].match(/.{1,4}/g) ?? []).map((h) => parseInt(h, 16))));
      }
    }
    for (const b of t.matchAll(/beginbfrange([\s\S]*?)endbfrange/g)) {
      for (const l of b[1].matchAll(/<([0-9a-fA-F]+)>\s*<([0-9a-fA-F]+)>\s*(?:<([0-9a-fA-F]+)>|\[([^\]]*)\])/g)) {
        const a = parseInt(l[1], 16);
        const z = parseInt(l[2], 16);
        if (l[3]) { let u = parseInt(l[3], 16); for (let k = a; k <= z; k += 1) map.set(k, String.fromCodePoint(u++)); }
        else { const arr = [...l[4].matchAll(/<([0-9a-fA-F]+)>/g)].map((x) => String.fromCodePoint(parseInt(x[1], 16))); for (let k = a; k <= z; k += 1) map.set(k, arr[k - a] ?? ""); }
      }
    }
    res = { map, twoByte: /Identity-H/.test(f.dict) || [...map.keys()].some((k) => k > 255) };
  }
  cmaps.set(fontId, res);
  return res;
}
// 3) page order
function pageList() {
  const kids = [];
  const walk = (id) => {
    const o = objs.get(id);
    if (!o) return;
    if (/\/Type\s*\/Pages\b/.test(o.dict)) {
      const k = /\/Kids\s*\[([^\]]*)\]/.exec(o.dict);
      if (k) for (const r of k[1].matchAll(/(\d+) 0 R/g)) walk(+r[1]);
    } else kids.push(id);
  };
  const root = [...objs].find(([, o]) => /\/Type\s*\/Catalog/.test(o.dict));
  const pr = root && /\/Pages (\d+) 0 R/.exec(root[1].dict);
  if (pr) walk(+pr[1]);
  return kids.length ? kids : [...objs].filter(([, o]) => /\/Type\s*\/Page\b/.test(o.dict)).map(([id]) => id);
}
const unescape = (s) => s
  .replace(/\\([nrtbf])/g, (_, c) => ({ n: "\n", r: "\r", t: "\t", b: "\b", f: "\f" }[c]))
  .replace(/\\([0-7]{1,3})/g, (_, o) => String.fromCharCode(parseInt(o, 8)))
  .replace(/\\([()\\])/g, "$1");
const pages = pageList();
let out = "";
for (let pi = 0; pi < pages.length; pi += 1) {
  const pg = objs.get(pages[pi]);
  if (!pg) continue;
  const rr = /\/Resources\s*(\d+) 0 R/.exec(pg.dict);
  const resDict = rr ? objs.get(+rr[1])?.dict : pg.dict;
  const fi = /\/Font\s*<<([^>]*)>>/.exec(resDict ?? "");
  const fr = /\/Font\s*(\d+) 0 R/.exec(resDict ?? "");
  const fontDict = fi ? fi[1] : fr ? objs.get(+fr[1])?.dict ?? "" : "";
  const fonts = {};
  for (const f of fontDict.matchAll(/\/(\w+)\s+(\d+) 0 R/g)) fonts[f[1]] = +f[2];
  const contents = /\/Contents\s*(\[[^\]]*\]|\d+ 0 R)/.exec(pg.dict)?.[1] ?? "";
  const cids = [...contents.matchAll(/(\d+) 0 R/g)].map((x) => +x[1]);
  let text = "";
  let cur = null;
  const dec = (bytes) => {
    const cm = cur ? getCmap(cur) : null;
    if (!cm) return Buffer.from(bytes).toString("latin1");
    let s = "";
    if (cm.twoByte) for (let i = 0; i + 1 < bytes.length; i += 2) s += cm.map.get((bytes[i] << 8) | bytes[i + 1]) ?? "";
    else for (const b of bytes) s += cm.map.get(b) ?? String.fromCharCode(b);
    return s;
  };
  const tokRe = new RegExp(
    "/(\\w+)\\s+[\\d.]+\\s+Tf" + // font select
    "|\\[((?:[^\\]" + BS + BS + "]|" + BS + BS + ".)*)\\]\\s*TJ" + // TJ array
    "|\\(((?:[^()" + BS + BS + "]|" + BS + BS + ".)*)\\)\\s*Tj" + // Tj literal
    "|<([0-9a-fA-F]+)>\\s*Tj" + // Tj hex
    "|(T\\*|Td|TD|ET)(?![A-Za-z])",
    "g",
  );
  for (const cid of cids) {
    const d = objs.get(cid)?.data;
    if (!d) continue;
    const t = d.toString("latin1");
    let k;
    tokRe.lastIndex = 0;
    while ((k = tokRe.exec(t))) {
      if (k[1]) cur = fonts[k[1]] ?? null;
      else if (k[2] !== undefined) {
        let s = "";
        for (const p of k[2].matchAll(/\(((?:[^()\\]|\\.)*)\)|<([0-9a-fA-F]+)>|(-?[\d.]+)/g)) {
          if (p[1] !== undefined) s += dec(Buffer.from(unescape(p[1]), "latin1"));
          else if (p[2] !== undefined) s += dec(Buffer.from(p[2], "hex"));
          else if (+p[3] < -250) s += " ";
        }
        text += s;
      } else if (k[3] !== undefined) text += dec(Buffer.from(unescape(k[3]), "latin1"));
      else if (k[4] !== undefined) text += dec(Buffer.from(k[4], "hex"));
      else if (k[5]) text += "\n";
    }
  }
  out += `\n\n=== PAGE ${pi + 1} ===\n` + text.replace(/\n{2,}/g, "\n");
}
if (process.argv[3]) writeFileSync(process.argv[3], out);
console.log(`pages: ${pages.length}, chars: ${out.length}`);
